// Seeded random graph: 3 communities x 18 nodes.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(606);

const GROUPS = 3, PER = 18, N = GROUPS * PER;
const nodes = Array.from({ length: N }, (_, i) => ({
  g: Math.floor(i / PER),
  x: rand() * 2 - 1, y: rand() * 2 - 1, z: rand() * 2 - 1,
}));

const links = [];
for (let i = 0; i < N; i++) {
  for (let j = i + 1; j < N; j++) {
    const sameGroup = nodes[i].g === nodes[j].g;
    if (rand() < (sameGroup ? 0.16 : 0.012)) links.push([i, j]);
  }
}
// Ring inside each community guarantees it is connected.
for (let g = 0; g < GROUPS; g++)
  for (let k = 0; k < PER; k++)
    links.push([g * PER + k, g * PER + ((k + 1) % PER)]);

// Force layout: repulsion ~ 1/d^2, springs toward rest length, mild centering.
for (let iter = 0; iter < 300; iter++) {
  const cool = 1 - iter / 320;
  const fx = new Array(N).fill(0), fy = new Array(N).fill(0), fz = new Array(N).fill(0);

  for (let i = 0; i < N; i++) {
    for (let j = i + 1; j < N; j++) {
      let dx = nodes[i].x - nodes[j].x, dy = nodes[i].y - nodes[j].y, dz = nodes[i].z - nodes[j].z;
      const d2 = dx * dx + dy * dy + dz * dz + 0.01;
      const push = 0.05 / d2;
      const d = Math.sqrt(d2);
      dx /= d; dy /= d; dz /= d;
      fx[i] += dx * push; fy[i] += dy * push; fz[i] += dz * push;
      fx[j] -= dx * push; fy[j] -= dy * push; fz[j] -= dz * push;
    }
  }
  for (const [a, b] of links) {
    let dx = nodes[b].x - nodes[a].x, dy = nodes[b].y - nodes[a].y, dz = nodes[b].z - nodes[a].z;
    const d = Math.hypot(dx, dy, dz) || 0.001;
    const pull = 0.02 * (d - 0.9);
    dx /= d; dy /= d; dz /= d;
    fx[a] += dx * pull; fy[a] += dy * pull; fz[a] += dz * pull;
    fx[b] -= dx * pull; fy[b] -= dy * pull; fz[b] -= dz * pull;
  }
  for (let i = 0; i < N; i++) {
    fx[i] -= nodes[i].x * 0.004; fy[i] -= nodes[i].y * 0.004; fz[i] -= nodes[i].z * 0.004;
    nodes[i].x += fx[i] * cool; nodes[i].y += fy[i] * cool; nodes[i].z += fz[i] * cool;
  }
}

// Normalise into a tidy bounding box and publish.
let maxR = 0;
for (const n of nodes) maxR = Math.max(maxR, Math.hypot(n.x, n.y, n.z));
nb.set('graph3d', {
  nodes: nodes.map(n => ({
    g: n.g,
    x: +(n.x / maxR * 5).toFixed(3),
    y: +(n.y / maxR * 5).toFixed(3),
    z: +(n.z / maxR * 5).toFixed(3),
  })),
  links,
});

console.log(N + ' nodes, ' + links.length + ' links, 300 layout iterations');
console.log('published as graph3d - spin it below');
